def multiple_to_single(L):
    """
    Convert a list of multiple integers into a single integer by concatenating 
    their string representations.
    """
    # Handle the case where the first number is negative to preserve the sign
    # and ensure subsequent numbers are treated as absolute values for concatenation.
    res_str = ""
    for i in range(len(L)):
        if i == 0 and L[i] < 0:
            res_str += str(L[i])
        elif L[i] < 0:
            res_str += str(abs(L[i]))
        else:
            res_str += str(L[i])

    return int(res_str)

